def load() -> pd.DataFrame:
    import pandas as pd
    import glob
    paths = sorted(glob.glob('data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*.csv'))
    if not paths:
        raise FileNotFoundError('No files matched glob for State MSA Identity Theft data')
    return pd.DataFrame({'path': paths})
